def sort_values(values):
    if len(values) <= 1:
        return values[:]
    mid = len(values)//2
    left, right = sort_values(values[:mid]), sort_values(values[mid:])
    result, i, j = [], 0, 0
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:
            result.append(left[i]); i += 1
        else:
            result.append(right[j]); j += 1
    return result + left[i:] + right[j:]
